using System;
using System.Runtime.InteropServices;
using System.Threading;

namespace StayAwake.Agent
{
    /// <summary>
    /// Measures how long the user has been idle (no keyboard or mouse input).
    ///
    /// Default: GetLastInputInfo. Power requests from browsers, media players, or camera software
    /// ("keep the display on") do not affect it, so they cannot block the lock.
    ///
    /// IgnoreInjectedInput: low-level hooks that skip input generated by software (SendInput,
    /// mouse jigglers, "keep awake" utilities). Mouse events the system synthesizes from touch
    /// and pen still count. Must be created on a thread with a message loop (the UI thread).
    /// </summary>
    sealed class IdleMonitor : IDisposable
    {
        // Mouse messages generated from touch or pen carry this signature in dwExtraInfo.
        const uint TouchPenSignatureMask = 0xFFFFFF00;
        const uint TouchPenSignature = 0xFF515700;

        readonly bool _ignoreInjected;
        readonly Native.HookProc _keyboardProc, _mouseProc; // kept alive so the GC can't collect them
        IntPtr _keyboardHook = IntPtr.Zero, _mouseHook = IntPtr.Zero;
        System.Windows.Forms.Timer _rehook;
        int _lastRealInputTick;

        public IdleMonitor(bool ignoreInjected)
        {
            _ignoreInjected = ignoreInjected;
            _lastRealInputTick = Environment.TickCount;
            if (!ignoreInjected) return;

            _keyboardProc = KeyboardHook;
            _mouseProc = MouseHook;
            Install();
            // Windows silently drops low-level hooks that ever respond too slowly; reinstall periodically.
            _rehook = new System.Windows.Forms.Timer { Interval = 5 * 60 * 1000 };
            _rehook.Tick += (s, e) => { Uninstall(); Install(); };
            _rehook.Start();
        }

        public long IdleMilliseconds
        {
            get
            {
                if (_ignoreInjected)
                    return unchecked((uint)Environment.TickCount - (uint)Volatile.Read(ref _lastRealInputTick));

                var lii = new Native.LASTINPUTINFO { cbSize = Marshal.SizeOf(typeof(Native.LASTINPUTINFO)) };
                if (!Native.GetLastInputInfo(ref lii)) return 0;
                return unchecked((uint)Environment.TickCount - lii.dwTime);
            }
        }

        void Install()
        {
            IntPtr module = Native.GetModuleHandle(null);
            _keyboardHook = Native.SetWindowsHookEx(Native.WH_KEYBOARD_LL, _keyboardProc, module, 0);
            _mouseHook = Native.SetWindowsHookEx(Native.WH_MOUSE_LL, _mouseProc, module, 0);
        }

        void Uninstall()
        {
            if (_keyboardHook != IntPtr.Zero) { Native.UnhookWindowsHookEx(_keyboardHook); _keyboardHook = IntPtr.Zero; }
            if (_mouseHook != IntPtr.Zero) { Native.UnhookWindowsHookEx(_mouseHook); _mouseHook = IntPtr.Zero; }
        }

        IntPtr KeyboardHook(int nCode, IntPtr wParam, IntPtr lParam)
        {
            if (nCode >= 0)
            {
                // KBDLLHOOKSTRUCT: vkCode, scanCode, flags (offset 8)
                int flags = Marshal.ReadInt32(lParam, 8);
                if ((flags & Native.LLKHF_INJECTED) == 0) Volatile.Write(ref _lastRealInputTick, Environment.TickCount);
            }
            return Native.CallNextHookEx(_keyboardHook, nCode, wParam, lParam);
        }

        IntPtr MouseHook(int nCode, IntPtr wParam, IntPtr lParam)
        {
            if (nCode >= 0)
            {
                // MSLLHOOKSTRUCT: POINT pt (8), mouseData (4), flags (offset 12), time (4), dwExtraInfo (offset 16 + padding on x64)
                int flags = Marshal.ReadInt32(lParam, 12);
                int extraOffset = IntPtr.Size == 8 ? 24 : 20;
                uint extra = unchecked((uint)Marshal.ReadIntPtr(lParam, extraOffset).ToInt64());
                bool touchOrPen = (extra & TouchPenSignatureMask) == TouchPenSignature;
                if ((flags & Native.LLMHF_INJECTED) == 0 || touchOrPen)
                    Volatile.Write(ref _lastRealInputTick, Environment.TickCount);
            }
            return Native.CallNextHookEx(_mouseHook, nCode, wParam, lParam);
        }

        public void Dispose()
        {
            if (_rehook != null) _rehook.Dispose();
            Uninstall();
        }
    }
}
